import type { ImageProps } from 'antd';

import type { PreviewMedia } from '../lib/previewItems';
import { IconPlus } from './icons';

/** {@code preview} 那一坨配置的类型（{@code false} 与 {@code undefined} 是"不预览"，不是配置）。 */
export type ImagePreviewConfig = Exclude<ImageProps['preview'], boolean | undefined>;

/**
 * ★★DEV-268 第 3 条：会话级预览层的那一份配置（**整段会话一本相册**）。
 *
 * <h2>为什么它从 MessageBubble 搬到了这里</h2>
 *
 * <p>DEV-222 的「添加到表情」按钮原本挂在 {@code MessageBubble} 内部那几个
 * {@code Image.PreviewGroup} 上。DEV-268 把 group 提成了<b>会话级</b>（用户要的是
 * "左右键切换<b>对话中</b>的图片或视频"，一个网格一个 group 是做不到的）——
 * 于是这份配置的宿主也只剩下会话层（{@code ChatWindow}）一个。
 * ★搬出来而不是在 ChatWindow 里重写一份：预览层的按钮属于<b>同一个</b>判据
 * （"当前这张图在不在我的表情里"），复制一份必然与右键菜单那份分叉。
 *
 * <h2>★{@code imageRender}：把视频项画成能播的播放器</h2>
 *
 * <p>antd 的预览层只会画 {@code <img>}，而相册里现在<b>混着视频</b>（用户原话
 * "图片或视频"）。视频地址交给 {@code <img>} 的结果是一个空白/破图 —— 用户按右键翻到
 * 那条视频时会以为"这张图坏了"。所以命中视频项时换成一个带 controls 的 {@code <video>}。
 *
 * <p>★判据用 <b>url 反查 kind</b>（不用 {@code info.current} 去索引数组）：
 * 相册里可能有重复地址，而 {@code current} 是"第几张"，两者在去重/过滤口径上
 * 一旦不一致就会画错项。url 反查与"哪一项"是同一个来源。
 *
 * <p>★非视频项返回 antd 给的原节点（{@code originalNode}）—— 旋转/缩放/拖拽全在它身上，
 * 自己造一个 {@code <img>} 会把那些一起弄丢。
 */
export function buildMediaPreview(opts: {
  /** 相册内容（顺序即左右键的翻页顺序，见 {@code previewMediasOf}）。 */
  medias: readonly PreviewMedia[];
  /** 「添加到表情」的处理函数；不接 ⇒ 预览层里不出现这个按钮。 */
  onAddSticker?: (url: string) => void;
  /** 已经在表情里的地址（用来把按钮置灰，与右键菜单判重同源）。 */
  stickerUrls: readonly string[];
}): ImagePreviewConfig {
  const kindByUrl = new Map(opts.medias.map((m) => [m.url, m.kind]));

  const cfg: ImagePreviewConfig = {
    imageRender: (node, info) => {
      const url = info.image?.url ?? '';
      if (kindByUrl.get(url) !== 'video') return node;
      // ★不要 autoPlay：用户是"翻到"这一项的，不是在点它。
      return <video className="preview-video" src={url} controls />;
    },
  };

  const onAdd = opts.onAddSticker;
  if (!onAdd) return cfg;

  cfg.toolbarRender = (originalNode, info) => {
    const url = info.image?.url ?? '';
    // ★视频项不给「添加到表情」：收一个 .mp4 进表情，用户在用的时候得到的是一个
    //   放不出来的方块（表情面板渲染的是 <img>）。宁可不显示这个按钮。
    if (kindByUrl.get(url) === 'video') return originalNode;
    // ★已在表情里 ⇒ 置灰 + 写明（理由同 stickerAddNodesOf：可点但没反应比置灰更糟）。
    const dup = !!url && opts.stickerUrls.includes(url);
    return (
      <>
        <button
          type="button"
          className="preview-sticker-add"
          disabled={!url || dup}
          title={dup ? '这张图已经在你的表情里了' : '把这张图收进我的表情'}
          onClick={() => {
            if (url && !dup) onAdd(url);
          }}
        >
          <IconPlus size={13} />
          {dup ? '已在表情里' : '添加到表情'}
        </button>
        {originalNode}
      </>
    );
  };
  return cfg;
}
