import { App as AntApp } from 'antd';
import type { Id } from '../api/types';
import { useChatStore } from '../store/chat';
import { IconRefresh } from './icons';
import MemberPanelBody from './MemberPanelBody';
import PanelCloseButton from './PanelCloseButton';

/** ★ID 比较统一 String 归一（雪花 ID > 2^53，见 api/json.ts）。 */
const sameId = (a: unknown, b: unknown): boolean => a != null && b != null && String(a) === String(b);

/**
 * 会话窗口顶部「成员」标签页的<b>页内</b>形态。
 *
 * <p>★内容体与浮层版（{@link MemberDrawer}）共用 {@link MemberPanelBody} ——
 * 权限判定、大群降级提示、群主/管理员标记在两边必须逐字一致，
 * 复制一份出来迟早会有一边写错（理由详见那里的注释）。
 *
 * <p>★★DEV-246：切到这个标签页（= 面板重新挂载）时<b>会</b>拉一次成员表 ——
 * 依据是 {@link MemberPanelBody} 里那条"可见即拉"的 effect，
 * 本组件只是外壳，不重复做这件事。用户原话：
 *
 * <blockquote>「在空间添加成员时，会话这边人员数字变了，但是成员列表里没有变，
 * 可以做成点击成员时刷新列表吧」</blockquote>
 *
 * <p>★上面那个刷新按钮<b>保留</b>，它现在管的是另一种情形：面板<b>已经开着</b>的时候
 * 别人加了人（"可见即拉"只发生在打开的那一下）。两者不是重复入口 ——
 * 一个负责"打开时是最新的"，一个负责"正看着的时候我要最新的"。
 */
export default function ChatMembersPanel({
  convId,
  /**
   * ★DEV-194：成员卡片里点「发消息」之后，由外层切会话 + 弹回「消息」页。
   * 本组件只是把它透传给主体（成员列表的能力在两边必须一致，理由见类注释）。
   */
  onOpenChat,
  onClose,
}: {
  convId: Id | null;
  onOpenChat?: (convId: Id) => void;
  /**
   * ★DEV-253：关掉这条侧栏（由 {@code ChatWindow} 传"弹回「消息」页"）。
   * ★可选：不传就不渲染那个「×」—— 面板本身不知道"关掉我"是什么意思。
   */
  onClose?: () => void;
}) {
  const members = useChatStore((s) => (convId != null ? s.membersByConv[String(convId)] : undefined));
  const conv = useChatStore((s) => s.convs.find((c) => sameId(c.convId, convId)));
  const loadMembers = useChatStore((s) => s.loadMembers);
  const { message: toast } = AntApp.useApp();

  const total = conv?.memberCount ?? members?.length;
  const onRefresh = () => {
    if (convId == null) return;
    loadMembers(convId)
      .then(() => toast.success('成员已刷新'))
      .catch((e: unknown) => toast.error((e as Error).message));
  };

  return (
    <div className="chat-panel">
      <div className="chat-panel-head">
        <span className="chat-panel-title">成员{total != null ? ` · ${total} 人` : ''}</span>
        {/* ★DEV-253：右缘那一组（刷新 + 关闭）必须**成组**。直接把「×」追加在后面
            会让刷新按钮滑到标题旁边 —— 见 styles.css 里 .chat-panel-head-end 的注释。 */}
        <div className="chat-panel-head-end">
          <button className="icon-btn" title="刷新成员" onClick={onRefresh}>
            <IconRefresh size={15} />
          </button>
          {onClose && <PanelCloseButton onClose={onClose} panel="成员" />}
        </div>
      </div>
      <div className="chat-panel-scroll">
        <MemberPanelBody convId={convId} onOpenChat={onOpenChat} />
      </div>
    </div>
  );
}
