//   LEFT_KEYS/RIGHT_KEYS 与预算模块**同一份名单**：组件"整组收起不渲染组 div"
//   的分支必须和 layoutWidth 的"组收空不计 gap"分支同源，否则预算差 4px。
import { computeCollapsed, LEFT_KEYS, RIGHT_KEYS, type ToolbarItemKey } from '../lib/composerOverflow';
import {
  IconBold, IconBulletList, IconChevronDown, IconChevronLeft, IconClose, IconCode, IconEmoji,
  IconExpand, IconFontColor, IconItalic, IconLink, IconMentionAt, IconMore, IconOrderedList,
  IconPlus, IconPlusCircle, IconQuote, IconScreenshot, IconStrike, IconUnderline,
} from './icons';
