import SmartImg from './SmartImg';

/**
 * 输入框下方工具栏（2026-09-15，按用户给定参考图逐个补齐）。
 *
 * <p>布局与参考图一致：**左边是格式组**（B / I / U / S / 有序 / 无序 / 引用 / 链接 / 代码），
 * **右边是功能组**（Aa 字体、表情、@、截图、更多、展开）**加发送**，中间留空。
 *
 * <p>本组件只负责"发出意图"（{@code onFormat('bold')} 这样），
 * 真正的文本改写与选区管理在编辑器里 —— 因为只有它持有当前选区。
 * ★DEV-159 #5 之后这一层**一行都没改**：输入框从 textarea 换成 contenteditable 时，
 * 工具栏照旧只发意图，落地的实现（{@code lib/editor.ts} 的命令）整个换掉了，
 * 界面这一侧完全无感。这就是当初把它拆出来的意义。
 */

export interface ComposerToolbarProps {
  /** 平台模式下才允许上传（mock 模式没有文件服务，见 {@link MOCK_UPLOAD_HINT}）。 */
  canUpload: boolean;
  /** 上传进度 {done,total}；null = 空闲。 */
  uploading: { done: number; total: number } | null;
  /** 输入区是否处于展开态（决定 ↗ 的图标方向与提示语）。 */
  expanded: boolean;
  /** 有内容才能发送（空输入**且**没有待发送附件时发送按钮是灰的）。 */
  canSend: boolean;
  onFormat: (a: FormatAction) => void;
  /**
   * ★DEV-206 #214：给选中的文字上色 / 去色。
   * ★字段**缺席**表示"该属性保持不动"（只改文字色时不要动背景），
   * 显式 {@code null} 才是清掉 —— 见 {@code lib/editor.ColorSpec}。
   */
  onColor: (spec: ColorSpec) => void;
  onInsertText: (s: string) => void;
  /**
   * ★DEV-220：**我的表情**（服务端 {@code im_user_sticker}，已归一且过完安全闸门）。
   *
   * <p>★为什么由外面传进来而不是本组件自己读 store：本组件从 DEV-159 起就是
   * **纯展示组件**（只发意图，不碰 store），这条线一直没破过；
   * 而且归一化要用 {@code safeMediaUrl}，那份结果 MessageBubble 的右键菜单也要用
   * （判"这张图在不在我的表情里"）—— 两处各算一遍必然分叉。
   */
  stickers: StickerItem[];
  /** ★{@code true} = 还没问过服务端（store 里 {@code myStickers == null}）。
   *  空态文案要靠它区分"加载中"与"一张都没有"。 */
  stickersLoading: boolean;
  /**
   * ★DEV-217：点一张**图片表情**（表情面板）。
   *
   * <p>★刻意与 {@link onInsertText} 分开，而不是把图片也塞成一段 Markdown 文本：
   * 图片表情要成为一条有附件、有 `segments` 图片段的消息（这样它才在气泡里
   * 按正文位置渲染、才进得了文件列表、才搜得到），而"插一段 `![](...)` 文本"
   * 走的是另一条完全不同的路（那条路上没有附件、没有 fileName、搜不到）。
   *
   * <p>★★DEV-226 需求⑥（用户原话「表情点击时直接发送」）：**左键点格子就是它**，
   * 而且它现在**直接发出去**（一条只含这张图的独立消息），不再只是"塞进输入框等着"。
   * 想"把表情当正文配图、跟文字一起发"的用户走**右键** ⇒ {@link onInsertStickerInline}。
   */
  onPickSticker: (item: StickerItem) => void;
  /**
   * ★★DEV-226 需求⑥：把表情**插到输入框光标处**（旧的 {@code onPickSticker} 行为），
   * 现在挂在格子的**右键**上。
   *
   * <p>★为什么保留而不是一删了之：表情当正文里的配图是站得住的用法
   * （"今天长这样 😀图" 比"发一张图 + 再发一句话"更自然），而且这条路的实现
   * （{@code inline: true} 的待发送项 + 编辑器媒体节点）本来就在，删掉它等于
   * 把一个能用的能力悄悄拿掉。它只是**从主路径降级为次要入口**。
   *
   * <p>★右键必须 {@code preventDefault}：不拦的话浏览器会弹出自己的上下文菜单，
   * 盖在我们那一下操作之上（用户会以为"右键插入"没生效）。
   */
  onInsertStickerInline: (item: StickerItem) => void;
  /** ★DEV-220：面板刚被打开 ⇒ 顺手重拉一次我的表情（换设备加的表情要能看到）。 */
  onOpenStickers: () => void;
  /**
   * ★★DEV-318 需求①后半句：用户常用表情（store 的 {@code recentEmojis}）。
   *
   * <p>★形参类型是 {@code unknown}：进闸门之前一律是不可信输入
   * （与 {@link stickers} 由外面归一过不同 —— 常用列表<b>不做</b> URL 归一，
   * 它只是一串字符，所以把闸门留在 {@code quickEmojis} / {@code hasRecentEmojis} 里，
   * 这里不做任何假设）。{@code null} = 还没问过服务端。
   */
  recentEmojis: unknown;
  /**
   * ★★DEV-318 需求①：面板刚被打开 ⇒ 顺手重拉一次常用（对齐 {@link onOpenStickers}）。
   * ★<b>两个入口都要调</b>：工具栏表情 Popover 与「更多 ⋯ → 表情」——
   * 只挂一处的话，从「更多」进来的用户拿到的可能是几分钟前的旧列表。
   */
  onOpenEmojis: () => void;
  /**
   * ★★DEV-318 需求①：用户用了一个表情（拍板④：回应点选 + 输入框插入<b>都记</b>）。
   *
   * <p>★刻意与 {@link onInsertText} <b>分开</b>，而不是塞进 onInsertText 里：
   * {@code onInsertText} 是"往输入框插一段文本"的通用能力（将来别处也会用），
   * 把"记账"焊进去会让<b>任何</b>插入都变成一次"使用"。
   * ★调用点只有表情格子（普通表情与「常用」行两处），插入本身仍走 onInsertText。
   */
  onUseEmoji: (emoji: string) => void;
  /** ★DEV-220：面板里「添加」⇒ 由外面去开本地文件选择框（本组件不碰 DOM 输入框）。 */
  onAddSticker: () => void;
  /** ★DEV-220：删一张表情（外面负责二次确认后的调用与 toast）。 */
  onDeleteSticker: (item: StickerItem) => void;
  onMention: () => void;
  /** ★DEV-159：入口扩到四种类型（图片/视频/音频/文件），不再只有 image|file。 */
  onPickFile: (kind: AttachmentKind) => void;
  onScreenshot: () => void;
  onPasteImage: () => void;
  onToggleExpand: () => void;
  onSend: () => void;
}

/**
 * 工具栏上的一个图标按钮。
 *
 * <p>★{@code onMouseDown} 里的 {@code preventDefault} 是**必须**的，不是随手加的：
 * 不拦默认行为的话，按下按钮会先把焦点从 textarea 上夺走，
 * 而"格式作用于当前选区"依赖 textarea 的 {@code selectionStart/End} ——
 * 焦点一跑，用户看到的现象就是"点了没反应 / 作用在别处"。
 * 拦掉之后焦点始终留在输入框，选区也就始终是用户眼睛看到的那个。
 */
function ToolBtn({
  title, onClick, disabled, children, className,
}: {
  title: ReactNode;
  onClick?: () => void;
  disabled?: boolean;
  children: ReactNode;
  className?: string;
}) {
  return (
    <Tooltip title={title}>
      {/* ★disabled 的按钮不派发鼠标事件 ⇒ 必须套一层 span 才能 hover 出原因 */}
      <span className="composer-attach">
        <button
          type="button"
          className={`icon-btn${className ? ` ${className}` : ''}`}
          disabled={disabled}
          onClick={onClick}
          onMouseDown={(e) => e.preventDefault()}
        >
          {children}
        </button>
      </span>
    </Tooltip>
  );
}

/**
 * ★DEV-206 #214：取色面板的常用色。
 *
 * <p>用户拍板的是「**任意取色器**，存十六进制值」——antd 的 {@code ColorPicker} 自带
 * 色板/拾色器/吸管，色值的合法化由 {@code richdoc.normalizeColor} 兜底
 * （宽进：{@code #RGB} / {@code rgb()} / {@code #RRGGBB} 一律归一成小写 6 位）。
 * 这个 presets 只是**省一次拖动**的快捷方式，不是白名单：
 * 面板上的取色器仍然可以选任意颜色。
 *
 * <p>★两组色刻意分开：文字色需要足够的对比度（都是深色），背景色是"荧光笔"
 * （都是浅色）——把同一个色板同时喂给两边会出现"背景选了个深蓝、字全看不见"。
 */
const TEXT_COLORS = ['#1f2329', '#f54a45', '#ff8800', '#d4380d', '#34c724', '#3370ff', '#7f3bf5', '#8c8c8c'];
const BG_COLORS = ['#fff1b8', '#ffe8e8', '#fff3e0', '#e8f3ff', '#e8fff0', '#f2f3f5'];

/**
 * ★DEV-299：取色面板**提取成组件**。
 *
 * <p>为什么必须提取而不是在「更多 ⋯」面板里再抄一份 JSX：窄屏时 Aa 按钮会被收进
 * 「更多」面板，面板里要出现**同一块**取色 UI —— 抄一份就是两把尺子，将来改色板
 * 或改行为必漏一边（DEV-293 附件契约"同表两套契约"的教训同款）。提取后
 * Popover 与「更多」两处渲染的是**同一个组件**，漂移无从发生。
 *
 * <p>JSX 与提取前逐字一致（含 onMouseDown preventDefault 的注释），只是宿主换了。
 */
function ColorPanel({ onColor, textColor, setTextColor, bgColor, setBgColor }: {
  onColor: (spec: ColorSpec) => void;
  textColor: string | undefined;
  setTextColor: (c: string | undefined) => void;
  bgColor: string | undefined;
  setBgColor: (c: string | undefined) => void;
}) {
  return (
    <div className="color-panel">
      {/* ★两行各自独立：只改文字色时**不动**背景（applyColor 里"缺席=保持"的语义），
          所以"无"也按行分开 —— 用户要的是"把背景去掉、红字留着"。
          ★onMouseDown 的 preventDefault 同工具栏按钮：不拦的话点面板会先把焦点
          从编辑器上夺走，而颜色作用在**当前选区**上，焦点一跑选区就没了。 */}
      <div className="color-row" onMouseDown={(e) => e.preventDefault()}>
        <span className="color-label">文字</span>
        <div className="color-swatches">
          {/* ★常用色做成**一次点击**的色块，而不是只塞进 ColorPicker 的 presets：
              用户最快的那条路（"把这句话标红"）应该是点一下就完事，
              而不是"打开取色器 → 在色板里找 → 点确定"。取色器负责其余颜色。 */}
          {TEXT_COLORS.map((c) => (
            <button
              key={c}
              type="button"
              className="color-swatch"
              style={{ background: c }}
              title={c}
              aria-label={`文字色 ${c}`}
              onClick={() => { setTextColor(c); onColor({ color: c }); }}
            />
          ))}
          <ColorPicker
            size="small"
            disabledAlpha
            value={textColor}
            onChangeComplete={(c) => {
              const hex = c.toHexString();
              setTextColor(hex);
              onColor({ color: hex });
            }}
          />
          <button
            type="button"
            className="color-none"
            onClick={() => { setTextColor(undefined); onColor({ color: null }); }}
          >
            无
          </button>
        </div>
      </div>
      <div className="color-row" onMouseDown={(e) => e.preventDefault()}>
        <span className="color-label">背景</span>
        <div className="color-swatches">
          {BG_COLORS.map((c) => (
            <button
              key={c}
              type="button"
              className="color-swatch"
              style={{ background: c }}
              title={c}
              aria-label={`背景色 ${c}`}
              onClick={() => { setBgColor(c); onColor({ bg: c }); }}
            />
          ))}
          <ColorPicker
            size="small"
            disabledAlpha
            value={bgColor}
            onChangeComplete={(c) => {
              const hex = c.toHexString();
              setBgColor(hex);
              onColor({ bg: hex });
            }}
          />
          <button
            type="button"
            className="color-none"
            onClick={() => { setBgColor(undefined); onColor({ bg: null }); }}
          >
            无
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * ★DEV-299：表情面板**提取成组件**（同 ColorPanel 的理由：Popover 与「更多 ⋯」
 * 两处宿主渲染同一份 JSX，不抄第二遍）。
 *
 * <p>★{@code onDone} 是唯一的语义抽象点：原来格子上写死 {@code setEmojiOpen(false)}，
 * 提取后"点完格子要关谁"由宿主决定 —— Popover 宿主关 emojiOpen，「更多」宿主关
 * moreOpen。**关面板的理由逐字不变**（见原注释：不关的话插入发生在输入框里、
 * 面板还挡在前面，用户看不到插入成功了没有）。
 */
function EmojiPanel({ p, onDone }: { p: ComposerToolbarProps; onDone: () => void }) {
  const stickerFull = p.stickers.length >= STICKER_MAX;
  /**
   * ★★DEV-318 需求①后半句：面板顶部的「常用」行。
   *
   * <p>两个判据（缺一不可）：
   * <ol>
   *   <li>{@link hasRecentEmojis} 为真 —— 常用为空时这一排会被默认集合补齐，
   *       与下面网格的前 8 个看起来是同一批表情，盖个「常用」标题就是<b>说假话</b>
   *       （用户会以为"系统已经知道我的习惯了"，其实一次都没记过）；</li>
   *   <li>★这一行<b>只放真实的</b>、<b>不补默认</b> —— 补默认是
   *       {@code ReactionPicker} 快捷条的做法，那条<b>没有标题</b>且固定 8 格
   *       （DEV-317 的观感必须保住）；这里有「常用」标题，且 279 个表情就在下面，
   *       补默认既重复又说假话。</li>
   * </ol>
   *
   * <p>★数据源与回应面板<b>同一份</b>：都读 store 的 {@code recentEmojis}、
   * 都过 {@code lib/emojiUsage} 的闸门（拍板④「两个面板共用同一份常用」）。
   */
  const recentList = hasRecentEmojis(p.recentEmojis)
    ? normalizeRecentEmojis(p.recentEmojis).slice(0, RECENT_QUICK_MAX)
    : [];
  /**
   * ★一个表情格子的**唯一**点击语义：先记账（{@link ComposerToolbarProps.onUseEmoji}），
   * 再插入，最后关面板。
   * ★顺序不能反：插入是会抛的（编辑器拿不到焦点等），记账放在后面就会被一起跳过 ——
   * 而"记账失败"不该影响"插入成功"这条主流程。
   */
  const cell = (e: string) => (
    <button
      key={e}
      type="button"
      className="emoji-cell"
      onClick={() => {
        p.onUseEmoji(e);
        p.onInsertText(e);
        onDone();
      }}
    >
      {e}
    </button>
  );
  return (
    <div className="emoji-panel">
      {recentList.length > 0 && (
        <div className="emoji-recent">
          <div className="emoji-recent-title">常用</div>
          <div className="emoji-grid emoji-recent-grid">
            {recentList.map((r) => cell(r.emoji))}
          </div>
        </div>
      )}
      <div className="emoji-grid">
        {EMOJIS.map((e) => cell(e))}
      </div>
      {/* ★★DEV-220：图片表情。数据源从【编译期常量】换成了【服务端表】
          （DEV-217 那 8 张自带的 SVG 已按用户要求删掉）——
          现在这里放的是**这个账号自己收藏的表情**，换设备也在。

          ★`p.stickers` 是外面归一过的（地址过 safeMediaUrl 才留下）：
          面板里出现一张**点得动但发不出去**的破图，比少一张图坏得多 ——
          用户不会知道那是数据的问题。 */}
      <div className="emoji-pack">
        <div className="emoji-pack-head">
          <span className="emoji-pack-title">我的表情</span>
          {/* ★DEV-220：添加 = 上传本地图片。★不能上传时（mock 模式没有文件服务）
              一并置灰并说明原因 —— 与工具栏另外两个上传入口同一口径。 */}
          <Tooltip title={p.canUpload
            ? (stickerFull ? `已达上限 ${STICKER_MAX} 张，先删几张再加` : '上传一张本地图片作为表情')
            : MOCK_UPLOAD_HINT}
          >
            <button
              type="button"
              className="sticker-add"
              aria-label="添加表情"
              disabled={!p.canUpload || stickerFull}
              onClick={() => p.onAddSticker()}
            >
              <IconPlus size={11} />
              添加
            </button>
          </Tooltip>
        </div>
        {p.stickersLoading ? (
          <span className="emoji-pack-empty">加载中…</span>
        ) : p.stickers.length === 0 ? (
          <span className="emoji-pack-empty">还没有表情，点「添加」上传一张</span>
        ) : (
          <div className="emoji-pack-grid">
            {p.stickers.map((s) => (
              // ★key 用 id 不用 name：服务端**允许重名**（名字缺省时从 URL 末段
              //   推导，两张不同的图完全可能都叫「表情」）。
              <div className="emoji-pack-cell" key={s.id}>
                <button
                  type="button"
                  className="sticker-pick"
                  /* ★★DEV-226 需求⑥：title 要说清两个键各做什么 ——
                     用户原话只说了「点击时直接发送」，右键那条路是**界面上看不见的**，
                     不在 title 里写出来就等于没有（没人会去右键试）。
                     ★别写成长句子：这是 tooltip，鼠标悬停一瞬就要读完。 */
                  title={`${s.name}（点击直接发送，右键插入到输入框）`}
                  /* ★aria-label 同取色面板那条：工具栏/面板里全是长得一样的格子，
                     量具靠名字点名，不数下标（插一项就会把后面所有下标挪一位）。 */
                  aria-label={`表情 ${s.name}`}
                  onClick={() => {
                    p.onPickSticker(s);
                    onDone();
                  }}
                  /* ★★DEV-226 需求⑥：右键 = 旧的"插到输入框光标处"。
                     ★preventDefault 必须在前：不拦下浏览器自带的上下文菜单，
                       它会盖在我们这次操作之上（用户看到的是"右键弹出个菜单"，
                       而不是"表情进了输入框"）。
                     ★同样 onDone()：不关面板的话，插入这件事在输入框里发生、
                       而面板还挡在它前面，用户看不到插入成功了没有
                       （与左键那条保持一致）。 */
                  onContextMenu={(e) => {
                    e.preventDefault();
                    p.onInsertStickerInline(s);
                    onDone();
                  }}
                >
                  {/* ★★DEV-249 需求①（也是挂账 #278）：加载失败时**不再留那个破图图标**，
                      改成一个中性占位块 + 名字首字。用户原话：「图片无法展示的不要展示
                      图裂的样子，展示默认头像」。
                      ★这里不能像头像那样"回落到首字色块"就完事 —— 表情格子里首字
                        本来就是随机的（用户给表情起的名字），所以占位块**刻意用中性灰**，
                        不调 avatarTone：给它上色会让人以为"这张表情本来就是这个色"。
                      ★`alt` 仍给 name（读屏可读），占位块另给 `aria-hidden`，
                        免得读屏把同一个名字念两遍。 */}
                  <SmartImg
                    className="emoji-pack-img"
                    src={s.url}
                    alt={s.name}
                    fallback={
                      <span className="emoji-pack-ph" aria-hidden="true">
                        {(s.name || '?').slice(0, 1)}
                      </span>
                    }
                  />
                </button>
                {/* ★删除是**物理删除、不可恢复**（服务端没有软删列），所以必须二次确认。
                    ★Popconfirm 默认朝上（top），而面板本来就在输入框上方 ——
                      跟着默认走会把确认框顶到屏幕外，所以显式改成朝下。
                    ★它必须挂在格子的**兄弟位置**而不是里面：格子本体是个 button，
                      按钮里套按钮是非法 HTML（浏览器会把内层拆出去，表现为"删除按钮
                      跑到格子外面"）。 */}
                <Popconfirm
                  title="删除这张表情？"
                  description="删除后无法恢复。已经发出去的消息不受影响。"
                  okText="删除"
                  cancelText="取消"
                  placement="bottom"
                  onConfirm={() => p.onDeleteSticker(s)}
                >
                  <button
                    type="button"
                    className="sticker-del"
                    aria-label={`删除表情 ${s.name}`}
                    title="删除"
                  >
                    <IconClose size={9} />
                  </button>
                </Popconfirm>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * ★DEV-299：「更多 ⋯」面板里的一行（图标 + 文字 + 点击即执行）。
 *
 * <p>★文字用**简洁版**而不是按钮 tooltip 的全文（"粗体"而不是"粗体（**文字**）"）：
 * 面板行有文字标签在旁边，图标不再需要靠 tooltip 自证身份；括号里的 Markdown
 * 语法提示在窄面板里只会挤换行。
 * <p>★aria-label = 行文字：量具点名不数下标（收拢项的数量随宽度变化，下标会漂）。
 */
function MoreRow({ icon, label, onClick, disabled }: {
  icon: ReactNode;
  label: string;
  onClick: () => void;
  disabled?: boolean;
}) {
  return (
    <button
      type="button"
      className="composer-more-item"
      aria-label={label}
      disabled={disabled}
      onClick={onClick}
    >
      <span className="composer-more-icon">{icon}</span>
      {label}
    </button>
  );
}

type MoreRowCtx = {
  p: ComposerToolbarProps;
  setMoreView: (v: 'main' | 'color' | 'emoji') => void;
  closeMore: () => void;
};

/**
 * ★DEV-299：被收起项 → 「更多 ⋯」面板行**构造表**（键与 COLLAPSE_ORDER 同一套
 * ToolbarItemKey，Record 类型逼着 15 个键一个都不能漏 —— 少一个键 tsc 直接红）。
 *
 * <p>三种形态（对应三种原控件，共同点 = 都不嵌套弹层）：
 * <ul>
 *   <li>即执行类（格式 9 项 / @ / 展开）：点了就干活，然后关面板；</li>
 *   <li>摊平类（截图 2 行 / ⊕ 3 行）：原下拉的每个菜单项**平铺**成面板行，
 *       少一层弹层就少一个 unmount 坑；disabled 跟随 canUpload（与工具栏同口径）；</li>
 *   <li>视图切换类（Aa / 表情）：大面板塞不进一行，点了切 moreView ——
 *       面板宿主还是那**一个** Dropdown，永远只有一层弹层。</li>
 * </ul>
 */
const MORE_ROWS: Record<ToolbarItemKey, (ctx: MoreRowCtx) => ReactNode> = {
  bold: ({ p, closeMore }) => <MoreRow key="bold" icon={<IconBold size={16} />} label="粗体" onClick={() => { p.onFormat('bold'); closeMore(); }} />,
  strike: ({ p, closeMore }) => <MoreRow key="strike" icon={<IconStrike size={16} />} label="删除线" onClick={() => { p.onFormat('strike'); closeMore(); }} />,
  italic: ({ p, closeMore }) => <MoreRow key="italic" icon={<IconItalic size={16} />} label="斜体" onClick={() => { p.onFormat('italic'); closeMore(); }} />,
  underline: ({ p, closeMore }) => <MoreRow key="underline" icon={<IconUnderline size={16} />} label="下划线" onClick={() => { p.onFormat('underline'); closeMore(); }} />,
  ordered: ({ p, closeMore }) => <MoreRow key="ordered" icon={<IconOrderedList size={16} />} label="有序列表" onClick={() => { p.onFormat('ordered'); closeMore(); }} />,
  bullet: ({ p, closeMore }) => <MoreRow key="bullet" icon={<IconBulletList size={16} />} label="无序列表" onClick={() => { p.onFormat('bullet'); closeMore(); }} />,
  quote: ({ p, closeMore }) => <MoreRow key="quote" icon={<IconQuote size={16} />} label="引用" onClick={() => { p.onFormat('quote'); closeMore(); }} />,
  link: ({ p, closeMore }) => <MoreRow key="link" icon={<IconLink size={16} />} label="链接" onClick={() => { p.onFormat('link'); closeMore(); }} />,
  code: ({ p, closeMore }) => <MoreRow key="code" icon={<IconCode size={16} />} label="行内代码" onClick={() => { p.onFormat('code'); closeMore(); }} />,
  shot: ({ p, closeMore }) => [
    <MoreRow key="shot-screen" icon={<IconScreenshot size={16} />} label="截取屏幕 / 窗口" disabled={!p.canUpload} onClick={() => { p.onScreenshot(); closeMore(); }} />,
    <MoreRow key="shot-clip" icon={<IconScreenshot size={16} />} label="粘贴剪贴板里的图片" disabled={!p.canUpload} onClick={() => { p.onPasteImage(); closeMore(); }} />,
  ],
  color: ({ setMoreView }) => <MoreRow key="color" icon={<IconFontColor size={16} />} label="字体颜色 / 背景" onClick={() => setMoreView('color')} />,
  emoji: ({ p, setMoreView }) => (
    <MoreRow
      key="emoji"
      icon={<IconEmoji size={16} />}
      label="表情"
      onClick={() => {
        // ★与工具栏表情 Popover 的 onOpenChange(true) 同一行为：打开时顺手重拉
        //   我的表情（DEV-220 口径）—— 收起态入口不降级。
        p.onOpenStickers();
        // ★★DEV-318 需求①：常用也必须在这里拉。这是表情面板的**第二个入口**
        //   （窄屏工具栏把表情收进「更多」时走的就是这条路）——
        //   只挂 Popover 那一处的话，窄屏用户永远看不到自己的常用。
        p.onOpenEmojis();
        setMoreView('emoji');
      }}
    />
  ),
  mention: ({ p, closeMore }) => <MoreRow key="mention" icon={<IconMentionAt size={16} />} label="提及成员" onClick={() => { p.onMention(); closeMore(); }} />,
  plus: ({ p, closeMore }) => [
    <MoreRow key="plus-image" icon={<IconPlusCircle size={16} />} label="发送图片" disabled={!p.canUpload} onClick={() => { p.onPickFile('image'); closeMore(); }} />,
    <MoreRow key="plus-video" icon={<IconPlusCircle size={16} />} label="发送视频" disabled={!p.canUpload} onClick={() => { p.onPickFile('video'); closeMore(); }} />,
    <MoreRow key="plus-file" icon={<IconPlusCircle size={16} />} label="发送文件（文档 / 音频等）" disabled={!p.canUpload} onClick={() => { p.onPickFile('file'); closeMore(); }} />,
  ],
  expand: ({ p, closeMore }) => (
    <MoreRow
      key="expand"
      icon={<IconExpand size={16} />}
      label={p.expanded ? '收起输入框' : '展开输入框（写长文）'}
      onClick={() => { p.onToggleExpand(); closeMore(); }}
    />
  ),
};

export default function ComposerToolbar(p: ComposerToolbarProps) {
  const [emojiOpen, setEmojiOpen] = useState(false);
  /** ★DEV-206：取色面板的展开态与"上一次选的色"（只是给色块按钮显示，不影响生效值）。 */
  const [colorOpen, setColorOpen] = useState(false);
  const [textColor, setTextColor] = useState<string | undefined>(undefined);
  const [bgColor, setBgColor] = useState<string | undefined>(undefined);
  // ★DEV-159：两个下拉（截图 / 更多）自己展开时**必须把 tooltip 收起来**。
  //   不自收的后果（浏览器实测抓到）：鼠标停在按钮上 → tooltip 弹在按钮**下方**、
  //   而菜单也从按钮下方展开 —— tooltip 的 z-index 更高，于是它盖住菜单**最后一项**。
  //   表现不是报错，而是"点「发送文件」没反应"，用户会以为功能坏了。
  const [shotMenuOpen, setShotMenuOpen] = useState(false);
  const [plusMenuOpen, setPlusMenuOpen] = useState(false);
  /* ★DEV-299：「更多 ⋯」面板的两个状态 —— open 之外还有 view：
     被收进面板的 Aa / 表情**自己也是面板**，嵌套弹层会踩 antd 的经典坑
     （点内层弹层被外层判定为 outside click ⇒ 外层关闭 ⇒ 内层整棵 unmount，
     用户看到"点了没反应"）。所以不做嵌套：点「字体颜色 / 背景」「表情」
     这两行时**切换面板内容**（main → color / emoji），弹层只有一层。 */
  const [moreOpen, setMoreOpen] = useState(false);
  const [moreView, setMoreView] = useState<'main' | 'color' | 'emoji'>('main');
  /* ★DEV-299：窄屏收拢的宽度来源。
     ★量的是**这条工具栏自己的 clientWidth**（= .composer 内容宽），不是 window：
     侧栏收展、分屏、平台 iframe 嵌入都会让"屏幕宽"与"发送框宽"脱钩（表单②拍板）。
     ★用 useLayoutEffect 而不是 useEffect：测量→收起发生在**首帧 paint 之前**，
     用户看不到"先全展开再缩回去"的闪动。
     ★ResizeObserver 缺席（jsdom/古董浏览器）时 typeof 防御照 ChatWindow:855 先例；
     availWidth 停在 0 ⇒ computeCollapsed 返回空 ⇒ 全展开 = 改动前的原样（fail-safe）。 */
  const rootRef = useRef<HTMLDivElement>(null);
  const [availWidth, setAvailWidth] = useState(0);
  useLayoutEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const measure = () => setAvailWidth(el.clientWidth);
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  /* 收起名单 = COLLAPSE_ORDER 的前缀（宽度预算见 lib/composerOverflow.ts）。
     uploading 参与预算：进度条占 ~90px，上传中收窄的窗口要提前多收一项。 */
  const collapsed = useMemo(
    () => computeCollapsed(availWidth, { uploading: p.uploading != null }),
    [availWidth, p.uploading],
  );
  const isHidden = (k: ToolbarItemKey) => collapsed.includes(k);
  const fmt = (a: FormatAction) => () => p.onFormat(a);
  /* ★DEV-220 的 stickerFull 判断随表情面板一起搬进了 EmojiPanel（两处宿主共用），
     主组件不再持有一份 —— 两份"满了没满"的判断就是两把尺子。 */

  return (
    <div className="composer-toolbar" ref={rootRef}>
      {/* ---------------- 左：格式组 ----------------
          ★DEV-299：每项套 isHidden 条件；**全组收起时整个 div 不渲染** ——
          留一个空 div 会白占两个顶层 gap（4px），预算模型里"组收空不渲染"
          与这里必须同一口径（composerOverflow.ts 的 layoutWidth 同款分支）。 */}
      {!LEFT_KEYS.every(isHidden) && (
      <div className="toolbar-group">
        {/* ★顺序严格照参考图：B → S → I → U（删除线在斜体前面）。
            这一组是"照着图片一个一个抄"的部分，顺序本身就是保真度的一部分，
            所以不要按"B/I/U/S 更常见"的直觉重排。 */}
        {!isHidden('bold') && <ToolBtn title="粗体（**文字**）" onClick={fmt('bold')}><IconBold size={18} /></ToolBtn>}
        {!isHidden('strike') && <ToolBtn title="删除线（~~文字~~）" onClick={fmt('strike')}><IconStrike size={18} /></ToolBtn>}
        {!isHidden('italic') && <ToolBtn title="斜体（*文字*）" onClick={fmt('italic')}><IconItalic size={18} /></ToolBtn>}
        {!isHidden('underline') && <ToolBtn title="下划线（<u>文字</u>）" onClick={fmt('underline')}><IconUnderline size={18} /></ToolBtn>}
        {!isHidden('ordered') && <ToolBtn title="有序列表（对选中的每一行生效）" onClick={fmt('ordered')}><IconOrderedList size={18} /></ToolBtn>}
        {!isHidden('bullet') && <ToolBtn title="无序列表（对选中的每一行生效）" onClick={fmt('bullet')}><IconBulletList size={18} /></ToolBtn>}
        {!isHidden('quote') && <ToolBtn title="引用（对选中的每一行生效）" onClick={fmt('quote')}><IconQuote size={18} /></ToolBtn>}
        {!isHidden('link') && <ToolBtn title="链接：先选中要当标题的文字，再点这里补全地址" onClick={fmt('link')}><IconLink size={18} /></ToolBtn>}
        {!isHidden('code') && <ToolBtn title="行内代码（`代码`）" onClick={fmt('code')}><IconCode size={18} /></ToolBtn>}
      </div>
      )}

      <span className="toolbar-spacer" />

      {p.uploading && (
        <span className="upload-progress">上传中 {p.uploading.done}/{p.uploading.total}</span>
      )}

      {/* ---------------- 右：功能组 ----------------
          ★DEV-299：与左组同款 —— 每项套 isHidden 条件，整组收起时组 div 不渲染
          （与 composerOverflow.layoutWidth 的"组收空不计 gap"同一口径）。
          ★Aa 取色与表情两个面板已提取为 ColorPanel / EmojiPanel：
          被收进「更多 ⋯」时**同一个组件**在面板里再渲染一次（同一把尺子，零漂移）。 */}
      {!RIGHT_KEYS.every(isHidden) && (
      <div className="toolbar-group">
        {!isHidden('color') && (
        <Popover
          trigger="click"
          placement="topRight"
          open={colorOpen}
          onOpenChange={setColorOpen}
          content={
            <ColorPanel
              onColor={p.onColor}
              textColor={textColor}
              setTextColor={setTextColor}
              bgColor={bgColor}
              setBgColor={setBgColor}
            />
          }
        >
          <span className="composer-attach">
            {/* ★★DEV-217 实测抓到的坑：**tooltip 会盖住面板右下角**。
                判据是浏览器给的 {@code elementFromPoint}：面板打开、鼠标停在按钮上时，
                「背景」那一行的「无」按钮中心命中的是 {@code DIV.ant-tooltip-inner}，
                而不是按钮本身 —— 也就是说用户点「去掉背景」**点不动**（点到了提示气泡上）。
                这跟下面「截图 / ⊕」两个下拉是同一条教训、同一个修法：
                自己展开时把 tooltip 强制收起（{@code false}），收起时交还给 antd（{@code undefined}）。 */}
            <Tooltip open={colorOpen ? false : undefined} title="字体颜色 / 背景">
              {/* ★DEV-216：加 aria-label 不只是可访问性 —— 工具栏十来个按钮**长得一样**
                  （都是一枚 18px 图标），脚本只能靠 `nth(i)` 找它们，而插入一个新按钮
                  就会把后面所有下标挪一位（DEV-214 的探针就踩过：注释里的编号与
                  `nth()` 各说各话）。有名字的按钮就别再靠位置找了。 */}
              <button
                type="button"
                className="icon-btn"
                aria-label="字体颜色 / 背景"
                onMouseDown={(e) => e.preventDefault()}
              >
                <IconFontColor size={18} />
              </button>
            </Tooltip>
          </span>
        </Popover>
        )}

        {!isHidden('emoji') && (
        <Popover
          open={emojiOpen}
          /* ★DEV-220：打开面板时顺手重拉一次我的表情 —— 表情存在账号上，
             用户完全可能刚在另一台设备上加了几张（下行帧里没有"表情变更"这一类）。
             ★只在**打开**时拉（v 为真），关的时候不拉。
             ★★DEV-318 需求①：常用同理（也是账号级数据、也没有任何推送通道）——
               用户刚在回应面板点过的表情，再打开这里必须看得到。 */
          onOpenChange={(v) => {
            setEmojiOpen(v);
            if (v) {
              p.onOpenStickers();
              p.onOpenEmojis();
            }
          }}
          trigger="click"
          placement="topRight"
          content={<EmojiPanel p={p} onDone={() => setEmojiOpen(false)} />}
        >
          <span className="composer-attach">
            {/* ★★同上（DEV-217 实测）：tooltip 正好压在面板**最后一列**上 ——
                当时抓到的是 8 张表情里最右边的「哭」中心命中了
                {@code DIV.ant-tooltip-inner}，用户看到的是"最后几个表情点了没反应"
                （现在格子的数量由用户自己决定，但这一列的坑一模一样）。修法与取色面板一致。 */}
            <Tooltip open={emojiOpen ? false : undefined} title="表情">
              {/* ★同上：给个名字，量具就不用数下标了。 */}
              <button
                type="button"
                className="icon-btn"
                aria-label="表情"
                onMouseDown={(e) => e.preventDefault()}
              >
                <IconEmoji size={18} />
              </button>
            </Tooltip>
          </span>
        </Popover>
        )}

        {!isHidden('mention') && (
        <ToolBtn title="提及成员（也可以直接输入 @）" onClick={p.onMention}><IconMentionAt size={18} /></ToolBtn>
        )}

        {!isHidden('shot') && (
        <Dropdown
          trigger={['click']}
          disabled={!p.canUpload}
          open={shotMenuOpen}
          onOpenChange={setShotMenuOpen}
          menu={{
            items: [
              { key: 'screen', label: '截取屏幕 / 窗口' },
              { key: 'clip', label: '粘贴剪贴板里的图片' },
            ],
            onClick: ({ key }) => (key === 'screen' ? p.onScreenshot() : p.onPasteImage()),
          }}
        >
          <span className="composer-attach">
            {/* open={false} 只在菜单展开期间生效，收起后交还给 antd 的悬停逻辑 */}
            <Tooltip
              open={shotMenuOpen ? false : undefined}
              title={p.canUpload ? '截图发送（截屏需在弹窗里选一个窗口或屏幕）' : MOCK_UPLOAD_HINT}
            >
              <button
                type="button"
                className="icon-btn composer-split"
                disabled={!p.canUpload}
                onMouseDown={(e) => e.preventDefault()}
              >
                <IconScreenshot size={18} />
                <IconChevronDown size={10} />
              </button>
            </Tooltip>
          </span>
        </Dropdown>
        )}

        {!isHidden('plus') && (
        <Dropdown
          trigger={['click']}
          disabled={!p.canUpload}
          open={plusMenuOpen}
          onOpenChange={setPlusMenuOpen}
          menu={{
            // ★DEV-159：图片 / 视频 / 文件 三类入口（accept 只做过滤提示，
            //   真正的类型判定在 lib/attachment.kindOf，用户可以切到"所有文件"）。
            //   ★音频不单列：选"文件"时按 MIME 会自动认成音频并渲染成播放器，
            //   单列一个入口只会让菜单更长、而没有任何行为差异。
            items: [
              { key: 'image', label: '发送图片' },
              { key: 'video', label: '发送视频' },
              { key: 'file', label: '发送文件（文档 / 音频等）' },
            ],
            onClick: ({ key }) => p.onPickFile(key as AttachmentKind),
          }}
        >
          <span className="composer-attach">
            <Tooltip
              open={plusMenuOpen ? false : undefined}
              title={p.canUpload ? '更多：图片 / 视频 / 文件' : MOCK_UPLOAD_HINT}
            >
              <button
                type="button"
                className="icon-btn"
                disabled={!p.canUpload}
                onMouseDown={(e) => e.preventDefault()}
              >
                <IconPlusCircle size={18} />
              </button>
            </Tooltip>
          </span>
        </Dropdown>
        )}

        {!isHidden('expand') && (
        <ToolBtn
          title={p.expanded ? '收起输入框' : '展开输入框（写长文用）'}
          onClick={p.onToggleExpand}
          className={p.expanded ? 'is-expanded' : undefined}
        >
          <IconExpand size={18} />
        </ToolBtn>
        )}
      </div>
      )}

      {/* ★DEV-299：「更多 ⋯」—— 只在**有项被收起**时出现（预算里它自己占 30+2，
          见 composerOverflow 的 hasMore 分支）。位置在发送按钮**左侧**：
          发送按钮永远是工具栏最右一个，这是"顶出去"病灶的反面钉死点。
          ★面板是 dropdownRender 自绘（antd Dropdown 的 menu 塞不下取色板/表情格），
          被收项按 COLLAPSE_ORDER 平铺成"图标+文字"行；截图与 ⊕ 的下拉**摊平**成
          直接可点的行（不套嵌套 Dropdown）；Aa / 表情两个大面板走 moreView
          **视图切换**（不套嵌套 Popover）—— 三种手法共同避开同一个 antd 坑：
          点内层弹层 = 外层的 outside click ⇒ 外层关闭 ⇒ 内层 unmount ⇒ "点了没反应"。
          ★容器上的 onMouseDown preventDefault 与 ToolBtn 同款：保住编辑器焦点/选区
          （格式与颜色都作用于"用户眼睛看到的那个选区"）。 */}
      {collapsed.length > 0 && (
      <Dropdown
        trigger={['click']}
        open={moreOpen}
        onOpenChange={(v) => {
          setMoreOpen(v);
          // 关闭时回到主视图：下次打开不该还停在取色/表情页
          if (!v) setMoreView('main');
        }}
        placement="topRight"
        dropdownRender={() => (
          <div
            className="composer-more-panel"
            onMouseDown={(e) => e.preventDefault()}
          >
            {moreView === 'main' && (
              <>
                {collapsed.map((k) => MORE_ROWS[k]({ p, setMoreView, closeMore: () => setMoreOpen(false) }))}
              </>
            )}
            {moreView === 'color' && (
              <>
                <button
                  type="button"
                  className="composer-more-back"
                  aria-label="返回更多"
                  onClick={() => setMoreView('main')}
                >
                  <IconChevronLeft size={12} /> 返回
                </button>
                <ColorPanel
                  onColor={p.onColor}
                  textColor={textColor}
                  setTextColor={setTextColor}
                  bgColor={bgColor}
                  setBgColor={setBgColor}
                />
              </>
            )}
            {moreView === 'emoji' && (
              <>
                <button
                  type="button"
                  className="composer-more-back"
                  aria-label="返回更多"
                  onClick={() => setMoreView('main')}
                >
                  <IconChevronLeft size={12} /> 返回
                </button>
                <EmojiPanel p={p} onDone={() => setMoreOpen(false)} />
              </>
            )}
          </div>
        )}
      >
        <span className="composer-attach">
          {/* open={false} 只在面板展开期间生效（DEV-217 tooltip 盖面板的同款修法） */}
          <Tooltip open={moreOpen ? false : undefined} title="更多">
            <button
              type="button"
              className="icon-btn"
              aria-label="更多"
              onMouseDown={(e) => e.preventDefault()}
            >
              <IconMore size={18} />
            </button>
          </Tooltip>
        </span>
      </Dropdown>
      )}

      {/* ★这里是文字「发送」而不是参考图里的 ➤ 纸飞机：
          发送按钮的形态由用户上一轮明确指定（微信参考图里就是文字按钮），
          本轮的参考图补的是**其余图标**，两者不冲突。 */}
      <Tooltip title="发送（Enter）">
        <button type="button" className={`send-btn${p.canSend ? ' ready' : ''}`} onClick={p.onSend}>
          发送
        </button>
      </Tooltip>
    </div>
  );
}
