import { useState } from 'react';
import { Popover } from 'antd';
import type { ReactElement } from 'react';
import type { ConversationMemberDto, ConversationSummaryDto, Id } from '../api/types';
import { useChatStore } from '../store/chat';
import { avatarSrcOf } from '../lib/contact';
import UserCard from './UserCard';

/**
 * ★★DEV-314 ④（用户原话：「点击头像先展示用户名片，名片上展示我修改过的备注名，
 * 点击名片上的头像才看大图」）：**点头像 ⇒ 出名片** 的唯一落点组件。
 *
 * <h2>它解决的是一件"四处开花"的事</h2>
 *
 * <p>用户点名的四处：<b>消息气泡左侧头像 / 会话顶栏头像（私聊）/ 群成员面板头像 /
 * 智联录列表头像</b>。每处都手抄一遍
 * 「{@code <Popover trigger="click" overlayClassName="user-card-popover">
 * <UserCard …/></Popover>}」+ 一段"从 userId 找出成员行"的解析，
 * 就是四份各自漂移的实现 —— 而漂移的表现是"有的地方点出来是名片、
 * 有的地方还是直接弹大图"，用户只会说"这个功能时好时坏"。
 *
 * <h2>★★为什么不用事件总线（与 lib/avatarPreview 的取舍不同）</h2>
 *
 * <p>{@code lib/avatarPreview} 用总线是因为**全屏预览层只能有一个**
 * （两层黑底叠着），而落点拿不到"该在哪弹"。名片不一样：它必须**贴着被点的那个头像**
 * 弹出（Popover 锚定在子节点上），所以锚点天然就在落点手上。用总线的话，
 * 得把 {@code getBoundingClientRect()} 塞进事件里、再由 ChatWindow 渲染一个
 * {@code position:fixed} 的 1×1 锚点 —— 多一层坐标搬运，还多一个
 * "祖先有没有 transform"的隐式约束。锚点跟着子节点走是最省事也最稳的形态。
 *
 * <h2>★成员行从 store 里找，找不到就**按已知字段合成一行**</h2>
 *
 * <p>消息气泡手上只有 {@code senderId/senderName/senderAvatar}，没有
 * {@code ConversationMemberDto}；智联录手上只有 {@code ContactItem}。
 * 两者都不是成员行，而 {@link UserCard} 要的是成员行。这里做一次解析：
 * <b>先在当前会话的成员表里按 userId 找</b>（找得到就拿到真实的角色/群名片，
 * 名片上的「群主」标签与群管理区才会正确），<b>找不到就用调用点给的
 * name/avatar 合成一行</b>（角色标签自然为空 —— 这比编一个角色好）。
 *
 * <p>★★<b>头像字段是唯一例外：它按「成员行 &gt; 调用点那张图」补位</b>
 * （{@code name}/角色/群名片都只认成员行）。理由见 {@code member} 那一段 ——
 * 一句话：成员行没头像而调用点有图时，"名片上换成姓氏首字"会让用户点的那个
 * 大图入口凭空消失，而那条路（智能体行、平台降级）是真实存在的。
 *
 * <p>★合成的成员行**只有展示所需的最小字段**：{@code owner}/{@code manager}/
 * {@code role}/{@code nickName} 全缺省 ⇒ {@code canSetRole}/{@code canSetNickName}
 * 一律为假 ⇒ 卡片的「群管理」整块不渲染。这是**正确的降级方向**：
 * 群管理动作（设管理员/设群名片）本来就只该从群成员面板发起，
 * 那里有完整的成员行做判据。
 *
 * <p>★{@code conv} 由调用点**显式**传，不在这里读 {@code activeConvId}：
 * 智联录那一处根本没有"当前会话"这回事（用户可能停在某个群会话上、却在智联录里
 * 点别人的头像 —— 读 activeConvId 会让那张名片冒出**另一个群**的管理按钮）。
 * 智联录因此传 {@code undefined}，卡片退化成"纯资料 + 动作按钮"。
 */
export default function UserCardTrigger({
  userId,
  fallbackName,
  fallbackAvatar,
  conv,
  onOpenChat,
  children,
}: {
  /** ★目标人的 IM subject id。为空时**不包 Popover**（原样渲染子节点）—— 见下面注释。 */
  userId?: Id | null;
  /** ★成员表里找不到这个人时用的展示名（消息气泡传 senderName、智联录传展示名）。 */
  fallbackName?: string;
  /** ★成员表里找不到这个人时用的头像地址。 */
  fallbackAvatar?: string;
  /** ★当前会话（群管理判据要用 ownerUserId/myRole）。没有会话上下文时传 undefined。 */
  conv?: ConversationSummaryDto | null;
  /** ★名片上「发消息」成功后切到那个单聊去（由外层决定要不要同时切标签页）。 */
  onOpenChat?: (convId: Id) => void;
  /** ★被锚定的那个头像节点（必须是单个元素，且能接受 ref 与 onClick）。 */
  children: ReactElement;
}) {
  const [open, setOpen] = useState(false);
  // ★只从**调用点给的 conv** 里找成员行，刻意**不**回落到 activeConvId
  //   （理由见类注释末段：智联录那一处会让名片冒出另一个群的管理按钮）。
  const members = useChatStore((s) =>
    conv?.convId != null ? s.membersByConv[String(conv.convId)] : undefined,
  );

  // ★userId 为空 ⇒ 不做任何包裹：没有"这个人"就没有名片，此时原样渲染子节点
  //   （与 lib/avatarPreview 的"空 src 直接丢弃"同一条纪律：宁可不反应，也不弹一张空名片）。
  if (userId == null || String(userId) === '') return children;

  const key = String(userId);
  const found = members?.find((m) => String(m.userId) === key);
  // ★★DEV-314 ④ 收口：成员行**在，但没有头像**时，回落到调用点手上那张图。
  //
  // <p>为什么"找到了行"还不够：{@code found.avatar} 为空有两种真实来源 ——
  // 平台资料没给这个主体头像（**智能体行**就是这样：成员行由 {@code loadUsers}
  // 装配，而智能体的头像往往查不到）、或平台这次查询降级了。这两种情况下气泡
  // （{@code m.senderAvatar} 快照）**照样画着图**，于是"点开名片却变成姓氏首字圆"
  // 就成了用户眼里的一句"时好时坏" —— 更糟的是**大图入口整个没了**
  // （{@code UserCard} 只在有 src 时才给那颗大头像挂 onClick）。
  //
  // <p>★回落是**单调**的：它只在成员行为空时补位，**永远不会覆盖**成员行给出的
  // 头像（那条才是"当前"的真源 —— 用户刚换过头像时，快照是旧的）。
  // ⇒ 顺序恒为「成员行 > 调用点那张图 > 姓氏首字」，与用户眼前看到的那个圆
  // 保持一致：他点的是哪张图，名片上就还是哪张图。
  //
  // <p>★{@code avatarSrcOf} 而不是裸 {@code ||}：空串/纯空白要归一成"没有"
  // （{@code <img src="">} 会画出一个破图图标，比首字圆更糟 —— 见 lib/contact）。
  const member: ConversationMemberDto = found
    ? { ...found, avatar: avatarSrcOf(found.avatar) ?? avatarSrcOf(fallbackAvatar) ?? undefined }
    : {
        userId,
        name: fallbackName,
        avatar: fallbackAvatar,
      };

  return (
    <Popover
      open={open}
      onOpenChange={setOpen}
      trigger="click"
      // ★与成员面板同一个位置（右侧）与同一个浮层类名 —— 两处名片必须长得一模一样，
      //   否则同一张卡片在"成员面板点开"和"消息头像点开"时会换一套内边距。
      placement="right"
      arrow={false}
      overlayClassName="user-card-popover"
      content={
        <UserCard
          member={member}
          conv={conv}
          onOpenChat={onOpenChat}
          onClose={() => setOpen(false)}
        />
      }
    >
      {children}
    </Popover>
  );
}
