import type { ConvFileDto, Id, MessageDto } from '../api/types';
import { safeMediaUrl } from '../api/uploadUrl';
import { isAttachmentKind, type AttachmentKind } from './attachment';

/**
 * ★会话附件的两条取数路径，同一个行模型 {@link ConvFileItem}（纯函数）。
 *
 * <h2>★DEV-300 之后：面板走服务端全量，本文件的"聚合"只剩灯箱预览在用</h2>
 *
 * <ul>
 *   <li>{@link convFileItemsOf}：把<b>服务端</b> {@code GET …/conversations/{id}/files}
 *       返回的附件行（{@link ConvFileDto}）映射成面板行。这是
 *       {@code ChatFilesPanel} 的唯一数据来源 —— 覆盖会话<b>全部</b>消息，
 *       不再受"只聚合已加载消息"的窗口限制。</li>
 *   <li>{@link collectConvFiles}：从<b>已加载的消息</b>里抽附件。面板迁走后它
 *       仍被 {@code previewItems.ts}（灯箱预览）使用 —— 预览本来就只该覆盖
 *       已加载的消息（在聊天里看得见的图才能点开放大），所以这不是遗留，是边界。</li>
 * </ul>
 *
 * <h2>★这里是「映射」，不是「信任边界」——但两道都做了</h2>
 *
 * <p>URL 合法性由 {@code MessageBubble} 负责（那里是渲染端唯一的闸门，见其注释）。
 * 本文件<b>不依赖</b>那一道的存在：两条路径都自己调 {@link safeMediaUrl} 并<b>丢弃</b>
 * 不合法的项。理由是这条数据会被<b>另一个组件</b>（文件面板）拿去直接渲染
 * （缩略图 {@code <img src>}、下载 {@code <a href>}），"另一处会过滤"这种约定
 * 在代码里活不过两次重构。★服务端 {@code ConvFileDto.url} 是<b>原样透传</b>的
 * （DEV-293①：服务端"看着可信"不能替代客户端"点开前再验一次"），所以这一道
 * 对服务端数据同样不可省。
 *
 * <h2>collectConvFiles 认的三种消息形态</h2>
 *
 * <ol>
 *   <li>{@code rich_text}：{@code body.attachments[]}（DEV-159 的多附件形态）；</li>
 *   <li>{@code image|file|video|audio}：{@code body.url} 单附件（老形态，存量消息很多）；</li>
 *   <li>其余（{@code text}/{@code card}/{@code system}…）：没有附件，跳过。</li>
 * </ol>
 */

/** 文件面板里的一项。 */
export interface ConvFileItem {
  /** ★列表 key：{@code msgId} + 附件在消息内的序号（同一条消息可挂 20 个附件）。 */
  key: string;
  msgId: Id;
  kind: AttachmentKind;
  /** ★已过 {@code safeMediaUrl}，所以一定非空且可安全渲染。 */
  url: string;
  fileName: string;
  /** 字节数；未知为 0（界面显示 "—" 而不是 "0 B"）。 */
  size: number;
  senderId: Id;
  /** 发送者展示名。★可能为 null（服务端快照缺失），由调用方按 senderId 兜底。 */
  senderName?: string;
  sendTime?: number;
}

/** 文件名取值：与后端 {@code ImMessageBodies.fileNameOf} 认的键一致（fileName / name）。 */
function fileNameOf(o: Record<string, unknown>): string {
  const raw = o.fileName ?? o.name;
  return typeof raw === 'string' && raw.trim() ? raw.trim() : '未命名文件';
}

/** 体积取值：非数字 / NaN / 负数一律当"未知"（0），而不是让界面显示 "NaN B"。 */
function sizeOf(o: Record<string, unknown>): number {
  const n = typeof o.size === 'number' ? o.size : Number.NaN;
  return Number.isFinite(n) && n > 0 ? n : 0;
}

/**
 * ★已撤回的消息不算文件。
 *
 * <p>判定口径与 {@code MessageBubble.isRevoked} <b>逐字对齐</b>：撤回后服务端把
 * {@code body} 整个置 null，所以"status=2 或（有 revokeTime 且没有任何内容）"才是撤回。
 * ★不能只看 {@code body == null}：本地乐观/降级路径上也可能出现空 body 的正常消息。
 *
 * <p>两处口径必须一致 —— 不一致会出现"聊天里那条已经是『已撤回』，文件面板里还挂着
 * 它的图"，而用户点开是 404。这是那种没人会写进 bug 单、但每次看到都别扭的错。
 */
function isRevoked(m: MessageDto): boolean {
  const hasContent = !!m.body?.text || (m.body?.attachments?.length ?? 0) > 0;
  return m.msgStatus === 2 || (!!m.revokeTime && !hasContent);
}

/**
 * 把一批消息聚合成文件列表（★DEV-300 后仅供灯箱预览 {@code previewItems.ts} 使用）。
 *
 * @param messages 当前会话已加载的消息（通常旧→新）。传 null/undefined/空数组都返回空数组。
 * @returns ★<b>新 → 旧</b>排列：预览切换顺序和聊天一致，"刚发的在前"，
 *          因为用户点开的是刚看过的图，不是来考古的。
 */
export function collectConvFiles(messages: readonly MessageDto[] | null | undefined): ConvFileItem[] {
  if (!messages?.length) return [];
  const out: ConvFileItem[] = [];

  /** 单条附件的收集（两种形态共用，保证 url 闸门只有一处）。 */
  const push = (
    m: MessageDto,
    idx: number,
    kind: AttachmentKind,
    rawUrl: unknown,
    o: Record<string, unknown>,
  ): void => {
    const url = safeMediaUrl(rawUrl);
    // ★不合法/缺失的 URL 直接不入列：文件面板的每一项都应当能点开，
    //   留一个点不动的行只会让人以为"下载坏了"。
    //   （聊天气泡那边相反 —— 那里必须留个位置说明"附件不可用"，
    //    否则"图坏了"与"消息是空的"长得一样。两处取舍不同是因为展示目的不同。）
    if (!url) return;
    out.push({
      key: `${String(m.msgId)}#${idx}`,
      msgId: m.msgId,
      kind,
      url,
      fileName: fileNameOf(o),
      size: sizeOf(o),
      senderId: m.senderId,
      senderName: m.senderName,
      sendTime: m.sendTime,
    });
  };

  // ★倒序遍历：结果是"新→旧"，且不必再排一次序。
  //   （不按 sendTime 排：服务端时间可能缺、可能因时钟漂移乱序，
  //     而数组顺序就是服务端给的 seq 顺序，它是权威的。）
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    const m = messages[i];
    if (!m || isRevoked(m)) continue;
    const body = m.body;
    if (!body) continue;
    const t = (m.msgType ?? '').toLowerCase();

    if (t === 'rich_text') {
      // ★运行时值来自服务端（可能是别的客户端写的、手改库的），
      //   所以按 unknown 逐字段判，而不是信 TS 的声明。
      const raw: unknown = (body as { attachments?: unknown }).attachments;
      if (!Array.isArray(raw)) continue;
      (raw as unknown[]).forEach((a, idx) => {
        const o = (a ?? {}) as Record<string, unknown>;
        // kind 认不出来按 file 收（与 MessageBubble 同口径：能下载总比看不见强）。
        push(m, idx, isAttachmentKind(o.kind) ? o.kind : 'file', o.url, o);
      });
      continue;
    }

    // 老的单附件形态：msgType 本身就是类型，url 在 body 顶层。
    if (isAttachmentKind(t)) {
      push(m, 0, t, (body as { url?: unknown }).url, body as Record<string, unknown>);
    }
  }

  return out;
}

/**
 * ★DEV-300：把服务端「按会话列附件」接口（{@code GET …/conversations/{id}/files}）
 * 返回的行映射成面板行。文件面板的唯一数据来源。
 *
 * <p>与 {@link collectConvFiles} 的<b>刻意差异</b>：
 * <ul>
 *   <li>★<b>不反转</b> —— 服务端已经是 seq DESC（新→旧），再反转就成了旧→新。
 *       数组顺序就是权威（与 collectConvFiles"倒序遍历才得到新→旧"是两回事）。</li>
 *   <li>不需要认消息形态/撤回 —— 服务端在 SQL 层就按 msg_type 过滤、
 *       在应用层就剔了撤回与清空（{@code deletedSeqs} + {@code isContentVisible} 双重过滤）。</li>
 * </ul>
 *
 * <p>与 collectConvFiles <b>逐字一致</b>的口径（两处必须同尺子，否则同一条附件
 * 在预览和面板里长得不一样）：
 * <ul>
 *   <li>{@code safeMediaUrl} 闸门：不合法/缺失的 URL 直接不入列（服务端透传 ≠ 可信，DEV-293①）；</li>
 *   <li>kind 认不出 ⇒ 按 {@code 'file'} 收（能下载总比看不见强）——
 *       ★服务端也声明了回落，但运行时<b>不信声明</b>：这个字段可能来自旧版 jar 或手改库；</li>
 *   <li>fileName 空白 ⇒ 「未命名文件」；size 非正数/非数字 ⇒ 0（界面显示「—」）；</li>
 *   <li>key = {@code msgId#index}（同一条消息的多附件行互不相同）。</li>
 * </ul>
 *
 * @param rows 服务端一页附件行（新→旧）。传 null/undefined/空数组都返回空数组；行内 null 跳过。
 * @returns ★保持入参数组顺序（新→旧），<b>不得反转</b>。
 */
export function convFileItemsOf(rows: readonly ConvFileDto[] | null | undefined): ConvFileItem[] {
  if (!rows?.length) return [];
  const out: ConvFileItem[] = [];
  for (const r of rows) {
    if (!r) continue;
    const url = safeMediaUrl(r.url);
    // ★与 collectConvFiles 同一道闸门、同一个取舍：不合法的 URL 直接不入列。
    if (!url) continue;
    out.push({
      // ★index 运行时可能缺（TS 声明不可信），回落 0 —— 不产出 "m1#undefined"。
      key: `${String(r.msgId)}#${typeof r.index === 'number' ? r.index : 0}`,
      msgId: r.msgId,
      kind: isAttachmentKind(r.kind) ? r.kind : 'file',
      url,
      // ★兜底口径与本地聚合共用同一对函数（fileNameOf/sizeOf），不许各写一份。
      fileName: fileNameOf({ fileName: r.fileName }),
      size: sizeOf({ size: r.size }),
      senderId: r.senderId,
      // ★null → undefined：界面用 `?? '…'` 兜底，"null" 字符串不许上屏。
      senderName: r.senderName ?? undefined,
      sendTime: r.sendTime ?? undefined,
    });
  }
  return out;
}

/** 面板上的分类筛选（'all' = 不筛）。 */
export type FileKindFilter = 'all' | AttachmentKind;

/** 按类型筛选。★纯函数，供单测钉住"筛选不会把数组改坏"。 */
export function filterConvFiles(items: readonly ConvFileItem[], f: FileKindFilter): ConvFileItem[] {
  return f === 'all' ? [...items] : items.filter((it) => it.kind === f);
}
