import { useEffect, useState } from 'react';
import { Alert, Button, Card, Select, Space, Spin, Typography } from 'antd';
import { isPlatformMode, PLATFORM_LOGIN_URL } from '../authMode';
import { useChatStore } from '../store/chat';

/**
 * ★登录页 —— 两种模式二选一渲染。
 *
 * <table border="1">
 *   <caption>两种模式</caption>
 *   <tr><th>模式</th><th>页面</th><th>为什么</th></tr>
 *   <tr><td>{@code mock}</td><td>用户下拉 + 登录按钮</td>
 *       <td>本地开发没有平台可登，需要一键造出任意身份（MockUserDirectory 9001~9010）</td></tr>
 *   <tr><td>{@code platform}</td><td>★<b>没有登录表单</b>：挂载即探测平台登录态</td>
 *       <td>★★凭据是同域 Cookie，由浏览器自动携带；前端<b>没有</b>凭据可填。
 *           在 IM 里放一个账号密码框，等于要把平台的密码收进 IM 的页面里 ——
 *           既是凭据处理面的扩大，也做不到（平台的登录流程/验证码/SSO 都不在 IM 这边）。</td></tr>
 * </table>
 *
 * <h2>★★平台模式下"未登录"与"平台不可用"必须分开</h2>
 *
 * <p>两者都进不到聊天页，但给用户看的东西必须不同：
 * <ul>
 *   <li>{@code 401} → "请先登录 agent-platform" + 平台入口链接（<b>用户能自己解决</b>）；</li>
 *   <li>{@code 503}/网络 → "暂时无法校验登录态，稍后重试"（<b>用户解决不了</b>，
 *       引导他去登录只会让他反复登录几十次然后来报"登录了也进不去"）。</li>
 * </ul>
 * <p>合并成一句"登录失败"是本节最容易犯的错，且代价直接落在客服量上。
 * 服务端侧同一条纪律见 {@code ImAuthInterceptor} 的四态表（503 不能回 401）。
 *
 * <h2>★探测只发一次（由 store 的 restoreSession 触发）</h2>
 *
 * <p>本页自己不调 {@code authApi.me()}：探测时机收在 {@code App} 挂载时的
 * {@code restoreSession()} 里，本页只读 {@code authProbe} 的<b>结果</b>。
 * 若本页也发一次，首屏会打两次 whoami（其中一次还会与另一次竞态，
 * 出现"先显示未登录、半秒后自己进去了"的闪烁）。
 */

/** ★mock 用户目录（与 MockUserDirectory 一致；9009 停用见其注释）。 */
const MOCK_USERS = [
  { value: 9001, label: '9001 · 张三 (zhangsan) · 群主' },
  { value: 9002, label: '9002 · 李四 (lisi) · 管理员' },
  { value: 9003, label: '9003 · 王五 (wangwu)' },
  { value: 9004, label: '9004 · 赵六 (zhaoliu)' },
  { value: 9005, label: '9005 · 孙七 (sunqi)' },
  { value: 9006, label: '9006 · 周八 (zhouba)' },
  { value: 9007, label: '9007 · 吴九 (wujiu)' },
  { value: 9008, label: '9008 · 路人甲 (stranger) · 非成员' },
  { value: 9009, label: '9009 · 停用账号 (disableduser)' },
];

export default function LoginPage() {
  return isPlatformMode ? <PlatformLogin /> : <MockLogin />;
}

// ============================================================ platform 模式

function PlatformLogin() {
  const authProbe = useChatStore((s) => s.authProbe);
  const authError = useChatStore((s) => s.authError);
  const probe = useChatStore((s) => s.probePlatformSession);

  // ★兜底触发：正常情况下 App 的 restoreSession 已经在跑（它会把 authProbe 推到 probing）。
  //   但"退出登录"后回到本页时没有任何人再触发探测 —— 那种情况下 authProbe 是
  //   unauthenticated（由 logout 设置），本页据此渲染"重新进入"，由用户点按钮触发。
  //   这个 effect 只处理一种残留情形：authProbe 停在 idle（探测从未发生，例如
  //   restoreSession 被异常打断）。不自动探测是为了避免"未登录 → 自动探测 → 未登录"
  //   这种每渲染一次打一次 whoami 的循环。
  const [autoTried, setAutoTried] = useState(false);
  useEffect(() => {
    // ★★判据必须读【实时】store（getState()），不能读渲染快照里的 authProbe（DEV-157）。
    //   本组件挂载时 store 初值恰好就是 'idle'（App 的 restoreSession 要到 effect 里
    //   才把它置成 'probing'），读快照 ⇒ 这个条件在每次首屏都成立 ⇒ 与 App 那次探测
    //   并发打两次 whoami，最终建起两条同 deviceId 的连接。
    //   ★即便如此仍可能与 App 撞车（子组件 effect 先于父组件执行），
    //   真正的收口在 store 的探测单飞（probePlatformSession）；这里保留兜底，
    //   只为"restoreSession 被异常打断"这一种残留情形留出口。
    if (useChatStore.getState().authProbe === 'idle' && !autoTried) {
      setAutoTried(true);
      probe().catch(() => undefined);
    }
  }, [authProbe, autoTried, probe]);

  const busy = authProbe === 'idle' || authProbe === 'probing';

  return (
    <div className="login-wrap">
      <Card className="login-card" title="Nuwax IM">
        <Space direction="vertical" style={{ width: '100%' }} size={16}>
          {busy && (
            <Space size={8}>
              <Spin size="small" />
              <Typography.Text>正在校验平台登录态…</Typography.Text>
            </Space>
          )}

          {!busy && authProbe === 'unavailable' && (
            <Alert
              type="warning"
              showIcon
              message="暂时无法校验平台登录态"
              description={
                <>
                  <div>{authError ?? '平台鉴权服务暂时不可用。'}</div>
                  <div style={{ marginTop: 6 }}>
                    ★这是<b>服务端/平台侧</b>的问题，重新登录解决不了。请稍后重试；
                    若持续如此请联系管理员。
                  </div>
                </>
              }
              action={
                <Button size="small" onClick={() => probe().catch(() => undefined)}>
                  重试
                </Button>
              }
            />
          )}

          {!busy && authProbe !== 'unavailable' && (
            <Alert
              type="info"
              showIcon
              message="请先登录 agent-platform"
              description={
                <>
                  {/* ★★DEV-168：把判据给出的"为什么没自动把你送走"顶到最前面。
                      ★以前 authError 只在 unavailable 那一支显示，于是
                      「平台要求跳转的地址不合法，已阻止自动跳转」与
                      「检测到跳转循环，已停止自动跳转」这两句话永远不出现在界面上 ——
                      用户只看到一句「请先登录」，而他明明刚在平台上登录过。
                      ★它不是错误详情，是【下一步该怎么做】的唯一线索：
                      这两种情况下"再去登一次"是没用的，用户必须手动开平台登录页。
                      ★为空时不渲染（普通的 401 走下面那段通用文案即可）。 */}
                  {authError && (
                    <div style={{ marginBottom: 6 }}>
                      <b>{authError}</b>
                    </div>
                  )}
                  <div>
                    IM 与 agent-platform 共用登录态（同一个域名下的登录 Cookie），
                    <b>IM 侧没有独立的账号密码入口</b>。
                  </div>
                  <div style={{ marginTop: 6 }}>请先在平台完成登录，然后回到本页。</div>
                </>
              }
            />
          )}

          <Space>
            <Button type="primary" href={PLATFORM_LOGIN_URL}>
              前往平台登录
            </Button>
            <Button onClick={() => probe().catch(() => undefined)} disabled={busy}>
              我已在平台登录，重新检测
            </Button>
          </Space>
        </Space>
      </Card>
    </div>
  );
}

// ============================================================ mock 模式

function MockLogin() {
  const [userId, setUserId] = useState<number>(9001);
  const [loading, setLoading] = useState(false);
  const login = useChatStore((s) => s.login);

  const onLogin = async () => {
    setLoading(true);
    try {
      const name = MOCK_USERS.find((u) => u.value === userId)?.label.split('·')[1]?.trim() ?? `user-${userId}`;
      await login(userId, name);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-wrap">
      <Card className="login-card" title="Nuwax IM · 开发登录">
        <Space direction="vertical" style={{ width: '100%' }} size={16}>
          <Typography.Text type="secondary">
            mock 鉴权模式（im.platform.auth-mode=mock）：选择用户即登录，token = mock-token-&#123;userId&#125;
          </Typography.Text>
          <Select
            style={{ width: '100%' }}
            value={userId}
            onChange={setUserId}
            options={MOCK_USERS}
          />
          <Button type="primary" block loading={loading} onClick={onLogin}>
            登录
          </Button>
        </Space>
      </Card>
    </div>
  );
}
