import { useState } from 'react';
import { Alert, App as AntApp, Empty, Input, List, Spin, Typography } from 'antd';
import { useQuery } from '@tanstack/react-query';
import { searchApi } from '../api';
import type { Id, MessageSearchItem } from '../api/types';
import { searchResultTime } from '../lib/msgTime';
import { useChatStore } from '../store/chat';
import PanelCloseButton from './PanelCloseButton';

/**
 * ★命中预览。口径与全局搜索（{@code SearchPanel.previewOf}）一致：
 * 附件消息在索引里没有正文，唯一可搜的是文件名，不标一下前缀的话
 * 结果里只剩一串孤零零的文件名，用户看不出它为什么命中、也看不出是个附件。
 */
function previewOf(m: MessageSearchItem): string {
  const frag = (m.highlight ?? m.text ?? m.fileName ?? '').replace(/<\/?em>/g, '');
  if (m.msgType === 'image') return `[图片] ${frag}`;
  if (m.msgType === 'file') return `[文件] ${frag}`;
  return frag;
}

/**
 * 会话窗口顶部「搜索」标签页：搜<b>当前会话</b>的消息。
 *
 * <h2>与全局搜索（{@code SearchPanel}）的分工</h2>
 *
 * <p>★两者<b>不是</b>同一件事，所以是两个组件、两个入口，没有合并：
 * 左栏那个放大镜是<b>跨会话</b>的全局搜索（搜到的结果点在别的会话上，
 * 会把你带走）；这一页是<b>本会话内</b>的查找（结果是"这个群里的哪句话"）。
 * 合并成一个的话，用户在一个群里按搜索却跳到了另一个群，那是很莫名其妙的体验。
 *
 * <p>共同点是都走同一个端点（{@code /search/messages}），只是这里恒带 {@code convId}。
 * 权限仍然是<b>服务端</b>判的（退群/被移除/解散 ⇒ 0 条），前端只管展示 ——
 * 这一点不能因为"是本会话"就以为可以省。
 *
 * <p>★提交式搜索（回车/点按钮才查）：输入过程不打 ES。ES 侧一次查询的开销
 * 与命中规模无关，逐字触发在长会话里会变成一串无意义的查询。
 */
export default function ChatSearchPanel({
  convId,
  onGoMessages,
  onClose,
}: {
  convId: Id | null;
  onGoMessages: () => void;
  /** ★DEV-253：关掉这条侧栏（面板不知道"关掉我"是什么意思，见 PanelCloseButton）。 */
  onClose?: () => void;
}) {
  const [keyword, setKeyword] = useState('');
  const [submittedKw, setSubmittedKw] = useState('');

  /**
   * ★DEV-269 第 3 条：复用 Pin 面板那条「定位原文」的通道（见 {@link doJump}）。
   * ★本组件只发请求 + 切页，真正的滚动与高亮在 {@code ChatWindow} 那个
   *   {@code focusRequest} 的 effect 里（与 {@code ChatPinPanel} 分工一字不差）。
   */
  const focusPinnedMessage = useChatStore((s) => s.focusPinnedMessage);
  const { message: toast } = AntApp.useApp();
  /** 正在定位的那条（按 msgId）。旧消息要发一次 history 请求 ⇒ 不给反馈会像卡住。 */
  const [jumping, setJumping] = useState<string | null>(null);

  const q = useQuery({
    queryKey: ['chatSearch', String(convId ?? ''), submittedKw],
    queryFn: () => searchApi.messages({ keyword: submittedKw, convId: convId ?? undefined, size: 50 }),
    enabled: convId != null && !!submittedKw,
  });

  const err = q.error as Error | null;
  const items = q.data?.items ?? [];

  /**
   * ★★DEV-269 第 3 条：点一条结果 ⇒ 切回「消息」标签页**并定位到那一条**。
   *
   * <p>用户原话：「搜索出来的消息点击没定位到原来的消息位置，还要考虑消息比较老的情况，
   * 在当前页面上没有，要能加载出来」。
   *
   * <h2>改之前是什么样</h2>
   *
   * <p>本组件里原本只调 {@code onGoMessages}（= 切回「消息」标签页），
   * 代码注释里当时写的理由是「Store 没有按 seq 跳转的能力，假装能跳然后只是滚到底，
   * 比不做更让人困惑」。**那个前提已经不存在了**：DEV-195 为 Pin 面板建的
   * {@code focusPinnedMessage(convId, msgId, seq)} 正是"按 seq 跳转"，
   * 而且里面已经处理了"这条不在内存里就拉一页历史补进来"这一步 —— 也就是用户说的
   * 「消息比较老、当前页面上没有，要能加载出来」。
   *
   * <p>DEV-208 把它复用给了第二个调用方（引用链路抽屉），那时它的 JSDoc 就写下了
   * 这条纪律：「**将来若出现第三个调用方，该做的仍然是复用这个方法**」。
   * 这里正是第三个调用方 —— 所以本组件<b>不新写一套滚动</b>，只接线。
   *
   * <h2>两件事的顺序不能反</h2>
   *
   * <p>先 {@code await focusPinnedMessage}（它可能发一次 history 请求，把目标那条
   * <b>弄进内存</b>），<b>再</b>切页。反过来的话，切到消息页的那一帧 ChatWindow
   * 在 DOM 里找不到目标节点 —— 而那个 effect 的设计是"找不到就<b>不</b>清请求、
   * 等 messages 变了再试"，虽然自愈，但会白滚一次。{@code ChatPinPanel.doJump}
   * 里那句注释说的就是这个。
   */
  const doJump = async (m: MessageSearchItem) => {
    if (convId == null) return;
    setJumping(String(m.msgId));
    try {
      await focusPinnedMessage(convId, m.msgId, m.seq ?? 0);
      onGoMessages();
    } catch (e) {
      // ★失败要说话：静默的话用户看到的是"点了没反应"，而事实是"定位失败"。
      //   与 ChatPinPanel.doJump 同款处置。
      toast.error(`定位原文失败：${(e as Error).message}`);
    } finally {
      setJumping(null);
    }
  };

  return (
    <div className="chat-panel">
      <div className="chat-panel-head">
        <span className="chat-panel-title">在本会话中搜索</span>
        {/* ★DEV-253：右缘那一组（这里只有关闭）。 */}
        <div className="chat-panel-head-end">{onClose && <PanelCloseButton onClose={onClose} panel="搜索" />}</div>
      </div>
      <div className="chat-panel-search">
        <Input.Search
          placeholder="输入关键词回车搜索（只搜这个会话）"
          value={keyword}
          onChange={(e) => setKeyword(e.target.value)}
          onSearch={(v) => setSubmittedKw(v.trim())}
          allowClear
          enterButton
        />
      </div>
      <div className="chat-panel-scroll">
        {err && <Alert type="error" showIcon style={{ marginBottom: 12 }} message={err.message} />}
        <List
          size="small"
          loading={q.isFetching}
          dataSource={items}
          locale={{
            emptyText: submittedKw ? (
              <Empty description="这个会话里没有匹配的消息（无权访问的消息不会出现）" />
            ) : (
              <Empty description="输入关键词后回车，只搜当前会话" />
            ),
          }}
          renderItem={(m) => (
            // ★点结果回「消息」标签页，而不是留在这里 —— 结果卡片里的上下文有限，
            //   用户真正想看的是它在聊天里的前后文。
            // ★★DEV-269 第 3 条：从「只切页」改成「切页 + 定位到那一条」（见 doJump）。
            //   ★那句"Store 没有按 seq 跳转的能力"的旧理由已作废 —— DEV-195 起有
            //     `focusPinnedMessage` 了。别再照旧注释理解现状。
            <List.Item
              style={{ cursor: 'pointer' }}
              onClick={() => void doJump(m)}
              /* ★DEV-268 第 2 条：用户原话「消息搜索出来的列表上展示时间」——
                 与全局搜索（{@code SearchPanel}）同款放在 `extra`（antd 靠右、与 Meta 垂直居中）。
                 ★不放 title 里：那样时间会跟着长文本换行，50 条结果的时间各落一个 x 位置。
                 ★DEV-249 需求⑩ 只做了全局搜索那一处，会话内这一页漏了 —— 同一句话的第二次报。
                 ★DEV-269：正在定位的那条把时间换成转圈（旧消息要发一次 history 请求）。 */
              extra={
                jumping === String(m.msgId) ? (
                  <Spin size="small" />
                ) : (
                  <Typography.Text style={{ fontSize: 12 }} type="secondary">
                    {searchResultTime(m.sendTime)}
                  </Typography.Text>
                )
              }
            >
              <List.Item.Meta
                title={<Typography.Text style={{ fontSize: 13 }}>{m.senderName ?? m.senderId}</Typography.Text>}
                description={
                  <Typography.Text style={{ fontSize: 12 }} type="secondary">
                    {previewOf(m)}
                  </Typography.Text>
                }
              />
            </List.Item>
          )}
        />
      </div>
    </div>
  );
}
