import { useState } from 'react';
import { App as AntApp, Button, Typography } from 'antd';
import type { CardAction, CardActionState, CardBody } from '../api/types';
import { safeMediaUrl } from '../api/upload';
import { actionViewOf, isActionClickable } from '../lib/card';
import SmartImg from './SmartImg';

/**
 * ★互动卡片（{@code msgType='card'}）的渲染 —— DEV-197-b。
 *
 * <h2>★★它同时承载两种东西，这是本组件最容易写错的地方</h2>
 *
 * <p>① <b>展示卡</b>（平台侧发的通知）：{@code title} / {@code desc} / {@code fields}，只读；
 * ② <b>交互卡</b>（DEV-197 起，服务端进程内发）：再加 {@code actions[]}，
 * 每个按钮点击后走 {@code POST /messages/{msgId}/actions/{actionKey}}。
 *
 * <p>两者**同一份渲染**，判据只有一条"有没有 {@code actions}"（空数组与缺失等价，
 * 见 {@code lib/card.ts}）。
 *
 * <h2>★★按钮的三种形态由服务端决定，这里一个字都不猜</h2>
 *
 * <p>状态取自 {@code card.actions[].state}（读消息时服务端回填），判据在
 * {@code lib/card.ts} 的 {@link actionViewOf} / {@link isActionClickable}，那里有单测：
 * <b>缺失即 pending（可点）</b>、<b>未知取值即不可点</b>、其余一律置灰并显示服务端给的
 * {@code text}。★<b>不要在这里写"申请是不是已经通过了"的判断</b> —— 猜不出来，也猜不准。
 *
 * <h2>★点击后不弹二次确认（刻意的）</h2>
 *
 * <p>照微信 / 钉钉的群邀请卡片：点「通过」即通过。理由是这个卡片的存在意义就是
 * "在通知里一步办完"，加一层 Modal 会让它退化成"还得去面板"。
 * ★需要写拒绝理由的场景由<b>审核面板</b>承担（那里有输入框）——
 * 两条路径共用服务端的同一段实现（见 openapi {@code convReviewJoinRequest}）。
 * ★将来若确实要给危险动作加确认，判据应当是 {@code actionType}（**且必须对未知类型有兜底**，
 * 否则服务端加一种动作就会打挂老客户端），而不是按钮文案。
 *
 * <h2>★★payload 一个字都不读</h2>
 *
 * <p>卡片的 {@code actions[].payload} 是服务端 handler 的参数（"通过还是拒绝"藏在里面），
 * 客户端<b>只回传 key</b>。本组件里没有任何一处引用它 —— 这不是遗漏，是纪律
 * （见 {@code lib/card.ts} 的文件头与 openapi {@code msgRunAction}）。
 */
export default function InteractionCard({
  card,
  onRun,
}: {
  card: CardBody;
  /**
   * ★执行一个动作（只回 {@code key}，外加可选的备注）。
   * 返回服务端给的新状态；抛异常 = 真的失败（{@code forbidden} / {@code stale} 走返回值，不抛）。
   *
   * <p>★不传时按钮一律置灰（而不是"可点但点了没反应"）——
   * 后者是"看着能用的死按钮"，比灰着更糟。
   */
  onRun?: (actionKey: string) => Promise<CardActionState>;
}) {
  const { message: toast } = AntApp.useApp();
  /**
   * ★正在执行的动作 key（防连点）。
   * ★只存 key 不存整条状态：按钮的"已处理/已失效"由 store 里的消息 body 驱动
   * （{@code runCardAction} 会把新状态合并回去）—— 本地再存一份就会出现两个真源。
   */
  const [busyKey, setBusyKey] = useState<string | null>(null);

  // ★iconUrl 与 body.url 是同一条信任边界（发送方可自由构造），必须过同一个闸门。
  //   不过闸门的话，一个 `javascript:` 的 icon 会以 <img src> 形态被浏览器忽略，
  //   但一个 `data:text/html,…` 在部分场景下不是 —— 渲染端的安全判断永远要自己做。
  const icon = safeMediaUrl(card.iconUrl);
  const link = safeMediaUrl(card.actionUrl);

  const onAction = async (action: CardAction) => {
    if (!onRun || busyKey) return;
    setBusyKey(action.key);
    try {
      await onRun(action.key);
      // ★成功不弹 toast：按钮就地变成「已通过 / 已拒绝」本身就是最好的反馈，
      //   再弹一条"操作成功"是重复的（与 Pin 面板同一个口径）。
    } catch (e) {
      // ★真正的失败（消息没了 / 不是卡片 / 网络）才走这里。
      //   ★forbidden / stale 在返回值里、不会走到这 —— 那是状态不是错误（见类注释）。
      toast.error(e instanceof Error && e.message ? e.message : '操作失败，请稍后重试');
    } finally {
      setBusyKey(null);
    }
  };

  return (
    <div className="im-card">
      <div className="im-card-head">
        {/* ★★DEV-249 需求①：卡片图标同样不能露破图。
            ★`fallback` 走默认的 null —— 与"这张卡片根本没有 iconUrl"那一支**逐字相同**的观感。
              给个灰块反而会让"没图标"和"图标坏了"看起来是两回事，而用户不该关心这个差别。
            ★外层那个 `{icon ? ... : null}` 不能删：SmartImg 只在拿到 src 之后才做失败判断，
              而 iconUrl 为空时我们要的是**一个 <img> 都不进 DOM**（见 SmartImg 类注释第二条）。 */}
        {icon ? <SmartImg className="im-card-icon" src={icon} alt="" /> : null}
        <span className="im-card-title">{card.title}</span>
      </div>

      {/* ★desc 是"兜底客户端唯一能读到的一段话"（契约：未升级的移动端只渲染 digest＝title+desc），
          所以它必须自足；这里原样展示，不做截断 —— 截断会把"申请人附言"这类关键信息切掉。 */}
      {card.desc ? <div className="im-card-desc">{card.desc}</div> : null}

      {card.fields?.length ? (
        <div className="im-card-fields">
          {card.fields.map((f, i) => (
            // ★key 用下标：fields 是纯静态展示（没有交互、不会重排），
            //   而 label 可能重复（"状态：待审 / 状态：已读"）。
            <div className="im-card-field" key={i}>
              <span className="im-card-field-label">{f.label}</span>
              <span className="im-card-field-value">{f.value}</span>
            </div>
          ))}
        </div>
      ) : null}

      {card.actions?.length ? (
        <div className="im-card-actions">
          {card.actions.map((a) => {
            const view = actionViewOf(a);
            // ★能不能点 = ①服务端说 pending ②父组件真的能执行。
            //   两者缺一就置灰：不能执行的按钮不该是可点的。
            const clickable = view.clickable && !!onRun;
            return (
              <Button
                key={a.key}
                size="small"
                className="im-card-btn"
                // ★style 只影响配色、不影响语义（契约明文）。映射：primary→primary、
                //   danger→danger、其余（含未知取值）→ default。★未知取值不报错、不隐藏，
                //   只按 default 画 —— 服务端加一种配色不该打挂老客户端。
                type={a.style === 'primary' ? 'primary' : 'default'}
                danger={a.style === 'danger'}
                disabled={!clickable}
                loading={busyKey === a.key}
                onClick={() => onAction(a).catch(() => undefined)}
              >
                {view.text}
              </Button>
            );
          })}
        </div>
      ) : null}

      {link ? (
        // ★rel="noopener noreferrer" 必须带（同 MessageBubble 的文件链接）：
        //   不带的话新开的页面能通过 window.opener 把当前页导航到钓鱼站，
        //   而当前页正是已登录的平台。
        <a className="im-card-link" href={link} target="_blank" rel="noopener noreferrer">
          查看详情
        </a>
      ) : null}

      {/* ★没有任何动作区、也没有跳转链接 ⇒ 补一句人话。
          契约要求 desc 自足，但"这张卡只让你看一眼"这件事本身值得说清楚 ——
          否则用户会去点卡片本身（它不可点），然后以为界面坏了。 */}
      {!card.actions?.length && !link ? (
        <Typography.Text type="secondary" className="im-card-hint">
          这是一条通知，无需操作
        </Typography.Text>
      ) : null}
    </div>
  );
}
